import { ConnectionsCreativityHomeContent } from './components';
import {
  useConnectionsCreativityHomeContentToggle,
  useConnectionsCreativityHomePageData,
} from './hooks';

export const ConnectionsCreativityHome = () => {
  const { isContentEnabled } = useConnectionsCreativityHomeContentToggle();
  const pageDataBundle = useConnectionsCreativityHomePageData();

  return (
    <ConnectionsCreativityHomeContent
      isContentEnabled={isContentEnabled}
      {...pageDataBundle}
    />
  );
};
